using System;using System.Linq;using System.Reflection;using UnityEngine;
class Program{
 static int checks,failures;static void Check(bool b,string s){checks++;if(!b)failures++;Console.WriteLine((b?"PASS ":"FAIL ")+s);}
 static void Put(object obj,string key,object v)=>obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(obj,v);
 static int Page(DigGame__ChoiceLevelPanel p)=>(int)p.GetType().GetField("_pageIndex",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(p);
 static object Call(object obj,string method,params object[] args)=>obj.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);
 static MainPanel main;static DigGame__ChoiceLevelPanel dig;
 static void Setup(int current=1,int saved=0,int count=25,int per=10){
  DB.DigGame=new(){CurrentLevel=current,ChoiceLevelPanelPageIndex=saved,UnlockLevels=Enumerable.Range(1,count).ToList()};DB.GameData=new(){CurrentLevel=current,ChioceLevelPanelPageIndex=saved};
  DB.DigWrites=DB.MainWrites=0;DB.DigDiskPage=DB.MainDiskPage=saved;DB.SaveOk=true;Trace.Calls.Clear();Trace.Errors.Clear();Trace.Warnings.Clear();ConfigManager.RemoteConfig.Open=true;Application.isPlaying=true;
  GameManager.Instance=new();PlayCtrl.Instance=new();main=new(){MaxCount=per};var ctrl=GameManager.Instance.DigGameLevel;
  for(int i=1;i<=count;i++){var path="data"+i;ctrl.LevelSorts.Add(new(){Id=i,Path=path});ctrl.Data[path]=new(){Id=path,Path="DLevel_"+i};var m=new LevelSort{Id=i,Path=path};main.sortDatas.Add(m);PlayCtrl.Instance.Level.levelsort.Add(m);PlayCtrl.Instance.Level.leveldatas[path]=new(){Id=path};}
  dig=new();Put(dig,"maxCount",per);Put(dig,"content",new RectTransform());Put(dig,"choiceLevelItem",new DigGame_LevelChoiceItem());Put(dig,"gridLayout",new RowFirstLayoutGroup());Put(dig,"lastBtn",new CustomButton());Put(dig,"nextBtn",new CustomButton());Put(dig,"closeBtn",new CustomButton());Put(dig,"quickTurnComp",new LevelChoicePanel_QuickTurn());GameManager.Instance.Panel=dig;dig.OnCreate();dig.OnOpen();main.OnOpen();main.Open();
 }
 static void Main(){
  foreach(int per in new[]{5,10})foreach(int current in new[]{1,10,11,25})foreach(int saved in new[]{-3,0,99}){Setup(current,saved,25,per);Check(Page(dig)==main.pageIndex&&Page(dig)==(current-1)/per,"当前有效关优先 per="+per+" current="+current+" saved="+saved);}
  Setup(999,1);Check(Page(dig)==main.pageIndex&&Page(dig)==1&&DB.DigGame.CurrentLevel==999&&DB.DigWrites==0,"首次创建当前ID失效回退保存页，不先回写第一关");
  Setup(17,2);GameManager.Instance.DigGameLevel.Data.Remove("data17");PlayCtrl.Instance.Level.leveldatas.Remove("data17");dig.OnOpen();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==2,"当前关配置缺失回退进关页");
  foreach(int saved in new[]{-9,99}){Setup(17,saved);GameManager.Instance.DigGameLevel.Data.Remove("data17");PlayCtrl.Instance.Level.leveldatas.Remove("data17");dig.OnOpen();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==Math.Clamp(saved,0,2),"旧保存页越界夹取 "+saved);}
  Setup(17,1);GameManager.Instance.DigGameLevel.LevelSorts.RemoveAll(v=>v.Id>10);main.sortDatas.RemoveAll(v=>v.Id>10);PlayCtrl.Instance.Level.levelsort.RemoveAll(v=>v.Id>10);Put(dig,"_sortData",GameManager.Instance.DigGameLevel.LevelSorts.ToList());dig.OnOpen();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==0,"排序缩短使当前ID缺失后回退并夹取保存页");
  Setup();Call(dig,"ChangePage",1);Call(dig,"OnQuickTurnPageChanged",2);main.Drag(2);Check(Page(dig)==main.pageIndex&&Page(dig)==2,"按钮与拖动显示目标页");Check(DB.DigWrites==DB.MainWrites&&DB.DigWrites==0&&DB.DigGame.ChoiceLevelPanelPageIndex==0,"浏览不保存页码");dig.OnClose();main.OnClose();Check(DB.DigWrites==0&&DB.MainWrites==0&&DB.DigDiskPage==0,"关闭不保存页码");dig.OnOpen();main.OnOpen();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==0,"浏览关闭后重开显示当前关");
  Setup();Call(dig,"ChangePage",2);main.Drag(2);dig.EnterLevel(GameManager.Instance.DigGameLevel.LevelSorts[20],GameManager.Instance.DigGameLevel.Data["data21"],1);main.EnterLevel(main.sortDatas[20]);Check(DB.DigWrites==1&&DB.MainWrites==1&&DB.DigDiskPage==DB.MainDiskPage&&DB.DigDiskPage==2,"选关进入才保存当前页");dig.OnClose();dig.OnOpen();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==2,"选关后重开定位进入关");
  Setup(1,1);DB.SaveOk=false;Call(dig,"ChangePage",2);dig.EnterLevel(GameManager.Instance.DigGameLevel.LevelSorts[20],GameManager.Instance.DigGameLevel.Data["data21"],1);Check(DB.DigGame.CurrentLevel==21&&DB.DigGame.ChoiceLevelPanelPageIndex==2&&DB.DigDiskPage==1&&Trace.Warnings.Any(v=>v.Contains("Failed to save selected level")),"保存失败沿用原警告/内存值且磁盘旧值不变");
  Setup();dig.EnterLevel(GameManager.Instance.DigGameLevel.LevelSorts[20],GameManager.Instance.DigGameLevel.Data["data21"],0);Check(DB.DigWrites==0&&DB.DigGame.CurrentLevel==1&&DB.DigGame.ChoiceLevelPanelPageIndex==0,"旧版本请求不写进关页");
  Setup();Check(dig.TryBeginRewardAd(1,GameManager.Instance.DigGameLevel.LevelSorts[0],GameManager.Instance.DigGameLevel.Data["data1"]),"有效广告请求受理");Call(dig,"ChangePage",2);Call(dig,"OnQuickTurnPageChanged",2);Call(dig,"ClosePanel",new CustomButton());Check(Page(dig)==0&&DB.DigWrites==0&&Trace.Calls.Count==0,"广告等待保持翻页/关闭门禁");dig.EndRewardAd();Call(dig,"ChangePage",2);Check(Page(dig)==2&&DB.DigWrites==0,"广告完成恢复浏览且不保存");
  Setup(1,1);Call(dig,"ChangePage",2);GameManager.Instance.DigGameLevel.LevelSorts.RemoveRange(5,20);GameManager.Instance.DigGameLevel.ConfigGeneration++;dig.RefreshRemoteConfig();Check(Page(dig)==0&&dig.ConfigGeneration==2&&DB.DigGame.ChoiceLevelPanelPageIndex==1&&DB.DigWrites==0,"排序减少只夹取显示页/刷新版本不保存页码");dig.OnClose();Check(DB.DigGame.ChoiceLevelPanelPageIndex==1,"远端刷新后关闭保留原进关页");
  Setup(17,2);GameManager.Instance.DigGameLevel.LevelSorts.Reverse();for(int i=0;i<25;i++)GameManager.Instance.DigGameLevel.LevelSorts[i].Id=i+1;GameManager.Instance.DigGameLevel.ConfigGeneration++;main.sortDatas.Reverse();for(int i=0;i<25;i++)main.sortDatas[i].Id=i+1;PlayCtrl.Instance.Level.levelsort=main.sortDatas.ToList();dig.OnOpen();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==1&&DB.DigWrites==0,"远端重排按顺序重新编号，重开仍按CurrentLevel定位且不保存页码");
  Setup(5,1);new HomeHarness().Click();Check(Page(dig)==main.pageIndex&&Page(dig)==0&&Trace.Calls.SequenceEqual(new[]{"dig"}),"首页入口不再跳最高可玩页");Trace.Calls.Clear();ConfigManager.RemoteConfig.Open=false;new HomeHarness().Click();Check(Trace.Calls.Count==0,"首页关闭配置门禁保留");
  foreach(bool loading in new[]{false,true}){Setup(5,1);new ExitHarness(loading,!loading).ExitToLevelSelection();main.Open();Check(Page(dig)==main.pageIndex&&Page(dig)==0&&Trace.Calls.SequenceEqual(new[]{"home","dig"}),"关内/加载中退出采用普通打开定位 loading="+loading);}
  Setup();new ExitHarness(false,false).ExitToLevelSelection();Check(Trace.Calls.SequenceEqual(new[]{"home"}),"选关页退出不会自动重开");
  Setup();Call(dig,"ChangePage",2);Check(dig.TryEnterOneLinkLevel(GameManager.Instance.DigGameLevel.LevelSorts[20],GameManager.Instance.DigGameLevel.Data["data21"],out var linkError)&&DB.DigGame.ChoiceLevelPanelPageIndex==2&&DB.DigWrites==1,"OneLink仍复用进关页保存链");
  Setup();dig.OnClose();dig.EnterLevel(GameManager.Instance.DigGameLevel.LevelSorts[20],GameManager.Instance.DigGameLevel.Data["data21"],1);Check(DB.DigWrites==0&&DB.DigGame.CurrentLevel==1,"已关闭面板拒绝进关写入");  Console.WriteLine("RESULT checks="+checks+" failures="+failures);Environment.ExitCode=failures==0?0:1;
 }
}